"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["7639"],{8047(e,a,t){t.r(a),t.d(a,{metadata:()=>n,default:()=>u,frontMatter:()=>r,contentTitle:()=>s,toc:()=>c,assets:()=>d});var n=JSON.parse('{"id":"explain/features_ae","title":"Device Management","description":"avc \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/explain/features_ae.md","sourceDirName":"explain","slug":"/explain/features_ae","permalink":"/personal-av-docs/docs/explain/features_ae","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/explain/features_ae.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"Device Management","sidebar_label":"Device Management","sidebar_position":99,"edition":"avc","source":"https://doc.airvantage.net/avc/features_ae","format":"md"}}'),o=t(4848),i=t(8453);let r={title:"Device Management",sidebar_label:"Device Management",sidebar_position:99,edition:"avc",source:"https://doc.airvantage.net/avc/features_ae",format:"md"},s,d={},c=[];function l(e){let a={a:"a",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsxs)(a.p,{children:[":::note Edition\n",(0,o.jsx)(a.strong,{children:"avc"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,o.jsx)(a.a,{href:"https://doc.airvantage.net/avc/features_ae",children:"Original page"}),".\n:::"]}),"\n",(0,o.jsx)(a.p,{children:"Device Management\nConnect any Hardware with AirVantage\nAirVantage provides simple integration with any hardware supporting MQTT.\nIt couldn\u2019t be easier! Just select your hardware, get a MQTT library for your platform and send data to AirVantage using the\nMQTT tutorial\n. (And the\nPAHO project\nsupplies a list of libraries in several languages).\nNeed some help ? Check our How-to tutorials, it covers some common devices. For each type, we explain how to send data and provide sample code for you to install.\nAPI to Integrate with the Enterprise\nAirVantage provides a comprehensive set of API you can use to quickly integrate your iot device to your business. For example\nIntegrate machine data into your enterprise software CRM, ERP\nBuild Smartphone or Tablet application feeded with real time data coming from connected devices\nKeep control of your fleet, deployed on the field and in your inventory, check and update the various configurations in operations\nSend commands or software updates to your entire fleet, or a selected portion, to change their behavior without having to send anyone on the field\nBuild your own service portal to serve your customers without having to expose AirVantage to your customers\nWe provide full documentation for the\nAPI\n, to get you started as easily as possible.\nMessage Queueing\nStore and forward high bandwidth device messages or events reliably at high pace to the enterprise using our Data Push option based on\nAMQP standard\n.\nBig Data Storage and Analytics\nTime Series Database\nAirVantage store any data sent in time series without any sub sampling, so you can access 100% of the data sent.\nThe\nSystem Last datapoints\nAPI can be used to get last data sent read a configuration, get the last known state of a machine (door open/closed, valve state) in order to report it in a map, a gauge or a status dashboard\nThe\nSystem Multi Raw datapoints\nAPI can be used when you need to access raw data for a period of time to diagnose a machine failure or behavior, to analyze some specific sensor data or perform some proprietary analytics.\nPre Defined Statistics\nAirVantage computes pre-defined statistics in real time: average value, minimum value, maximum value, sum of the values, count the number of datapoints sent, sum of squares of the values, standard deviation of the values, number of occurrences of the set of values. These statistics are available for a period of time given in the API: hour-hours, day-days, month-months, year-years. The statistics are available for any system and for the fleet.\nThe\nSystem Aggregated datapoints\nAPI Can be used to\nObserve trends and patterns from data. It is applicable to any data sent to AirVantage. Examples are car mileage, car speed, water pressure, water flow rate\nCompare the behavior of a machine to other data gathered in the same period of time\nCompare a machine with a reference one, a driver from another\nCount events: count goods sold on a vending machine, or hard break, collision, acceleration, speed limit reached from a car, page counts on a printer\nIdentify when an event occurred\nThe\nFleet aggregated datapoints\nAPI provides statistics for the entire fleet. The statistics for the fleet are computed from any statistic available for the systems; so you can get for a sensor data the minimum of the maximum, or average or minimum value, and so forth.\nDevelopment Tools\nDeploy IOT in days, not months.\nTimeline\nUse the AirVantange timeline to check or troubleshoot the communications from the device to AirVantage. The timeline gives you a real-time window on data communications sent to AirVantage.\nThe timeline notifies you when a new communication event occurs. To start debugging, just display this page and watch update notifications appear at the top of the page as data is received.\nThis page is a great way of identifying\nWhether a device is communicating\nWhat data the device sends, and when\nWhether this data is correctly understood on AirVantage\nThe frequency of each communication (check for lost communications)\nData Visualization\nAirVantage provides various ways to visualize any data sent to AirVantage\nCustomizable dashboard for the entire fleet. Can show a fleet consolidated view of the data sent\nCustomizable system view: choose the data you want to see\nIt helps you validate your embeded application without extra coding, and focus on your features. It can be used when your devices and applications are in the field, you can customize the user interface to show any data sent to AirVantage, look at the history, observe trends or issues.\nAlert Rules\nQuickly define alert rules in AirVantage, and be alerted as soon as a data is received from a device\nBe alerted when a device reaches or approaches a critical temperature\nBe alerted when a data usage of a site reaches a predefined level\nBe alerted when a valve is opened\nAlerts can trigger emails and also automatic calls to any external application listening to AirVantage:\nWebhook\n.\nOperations Management\nAirVantage helps you keep large scale deployment online and secure\nCentrally configure the hardware deployed in the field. Create configuration template and apply to multiple devices.\nUpdate modem firmware and embedded applications over-the-air.\nAdministration\nAirVantage provides a way for administrators to create new user accounts and define what they can see and do.\nAn Administrator can define new access profiles and assign them to users\nAudit log capture all operations with associated user\nUser access can be restricted using the user IP address\nMore AirVantage Features\nAnd that\u2019s just the tip of the iceberg! AirVantage provides many more features. Check out the\nAirVantage API Reference guide\nfor further details."})]})}function u(e={}){let{wrapper:a}={...(0,i.R)(),...e.components};return a?(0,o.jsx)(a,{...e,children:(0,o.jsx)(l,{...e})}):l(e)}},8453(e,a,t){t.d(a,{R:()=>r,x:()=>s});var n=t(6540);let o={},i=n.createContext(o);function r(e){let a=n.useContext(i);return n.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function s(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:r(e.components),n.createElement(i.Provider,{value:a},e.children)}}}]);